<template>
  <div class="app-container ps-page"><h2>评测报告与人工复核</h2>
    <div class="ps-toolbar"><el-input v-model="evaluationId" aria-label="评测记录 ID" placeholder="评测记录 ID" style="max-width:360px"/><el-button :loading="loading" @click="load">读取报告</el-button><el-button @click="download" :disabled="!report">下载报告</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <template v-if="report">
      <p>{{report.label}} · {{stateLabel(report.state)}}</p>
      <el-alert v-if="partialProgress" :title="partialProgress" type="info" :closable="false" class="ps-section"/>
      <div class="ps-grid"><el-card v-for="item in summaryCards" :key="item.key" shadow="never"><span>{{item.label}}</span><strong class="ps-card-value">{{metric(item.value,item.percent)}}</strong></el-card></div>
      <el-alert v-for="(diagnostic,i) in report.diagnostics||[]" :key="i" :title="diagnostic" type="warning" :closable="false" class="ps-section"/>
      <el-card v-if="agreement" shadow="never" class="ps-section"><template #header>评委与人工一致性</template><el-alert v-if="agreement.warning" :title="agreement.warning" type="warning" :closable="false" class="ps-section"/><el-descriptions :column="3" border><el-descriptions-item v-for="item in agreementMetrics" :key="item.label" :label="item.label">{{metric(item.value,item.percent)}}</el-descriptions-item><el-descriptions-item label="一致率下限">{{metric(agreement.minAgreementRate,true)}}</el-descriptions-item><el-descriptions-item label="最低可比较样本">{{agreement.minComparableCases}}</el-descriptions-item><el-descriptions-item label="Kappa 下限">{{agreement.minKappa==null?'未设置':metric(agreement.minKappa)}}</el-descriptions-item></el-descriptions><p v-if="agreement.disagreementCaseIds.length">分歧用例：<el-button v-for="id in agreement.disagreementCaseIds" :key="id" link type="primary" @click="selectById(id)">{{id}}</el-button></p></el-card>
      <el-collapse class="ps-section"><el-collapse-item title="评测冻结配置与预算"><pre class="ps-pre">{{JSON.stringify(report.configuration||report.config||{},null,2)}}</pre></el-collapse-item><el-collapse-item title="检索模式与诊断分布"><div class="ps-grid"><el-table :data="modeCounts"><el-table-column prop="name" label="检索模式"/><el-table-column prop="count" label="样本数"/></el-table><el-table :data="diagnosisCounts"><el-table-column prop="name" label="诊断" min-width="230"/><el-table-column prop="count" label="样本数" width="90"/></el-table></div></el-collapse-item><el-collapse-item title="诊断建议"><el-table :data="diagnosisGuide"><el-table-column prop="code" label="诊断编码" min-width="180"/><el-table-column prop="description" label="处理建议" min-width="420"/></el-table></el-collapse-item></el-collapse>
      <el-form inline><el-form-item label="问题"><el-input v-model="caseKeyword" clearable/></el-form-item><el-form-item label="诊断"><el-select v-model="caseDiagnosis" clearable><el-option v-for="entry in diagnosisGuide" :key="entry.code" :label="entry.description" :value="entry.code"/></el-select></el-form-item><el-checkbox v-model="onlyReview">仅需人工复核</el-checkbox></el-form>
      <el-table :data="visibleCases" v-loading="loading" highlight-current-row><el-table-column prop="id" label="用例" width="110"/><el-table-column prop="question" label="问题" min-width="250"/><el-table-column prop="retrievalMode" label="检索模式" min-width="140"/><el-table-column label="命中" width="85"><template #default="{row}">{{row.retrievalHit==null?'未标注':row.retrievalHit?'是':'否'}}</template></el-table-column><el-table-column label="Recall" width="100"><template #default="{row}">{{metric(row.recall,true)}}</template></el-table-column><el-table-column label="MRR" width="100"><template #default="{row}">{{metric(row.mrr??row.reciprocalRank)}}</template></el-table-column><el-table-column label="NDCG" width="100"><template #default="{row}">{{metric(row.ndcg)}}</template></el-table-column><el-table-column label="人工结论" min-width="130"><template #default="{row}">{{verdictLabel(row.humanVerdict?.correct)}}</template></el-table-column><el-table-column label="诊断" min-width="240"><template #default="{row}">{{diagnosisLabel(row.diagnosis)}} {{(row.diagnostics||[]).join('；')}}</template></el-table-column><el-table-column label="查看" width="90"><template #default="{row}"><el-button link type="primary" @click="select(row)">逐例复核</el-button></template></el-table-column></el-table>
    </template>
    <el-drawer v-model="open" title="逐例证据与人工复核" size="min(1050px,95vw)"><template v-if="selected"><h3>问题</h3><p class="ps-pre">{{selected.question}}</p><h3>独立预期</h3><pre class="ps-pre">{{selected.referenceAnswer||selected.expected||'评测集未提供参考答案'}}</pre><h3>实际回答</h3><pre class="ps-pre">{{selected.answer||'未生成回答'}}</pre><el-alert v-if="selected.error" :title="selected.error" type="error" :closable="false"/>
      <el-descriptions :column="2" border><el-descriptions-item label="检索模式">{{selected.retrievalMode||'未返回'}}</el-descriptions-item><el-descriptions-item label="首次相关排名">{{metric(selected.firstRelevantRank)}}</el-descriptions-item><el-descriptions-item label="倒数排名">{{metric(selected.reciprocalRank??selected.rr)}}</el-descriptions-item><el-descriptions-item label="期望文档覆盖率">{{metric(selected.expectedDocCoverage??selected.docCoverage??selected.coverage,true)}}</el-descriptions-item><el-descriptions-item label="耗时">{{metric(selected.latencyMs)}} ms</el-descriptions-item><el-descriptions-item label="诊断">{{diagnosisLabel(selected.diagnosis)}}</el-descriptions-item><el-descriptions-item label="需人工复核">{{selected.needsHumanReview?'是':'否'}} {{selected.reviewReason}}</el-descriptions-item></el-descriptions>
      <h3>实际检索证据</h3><el-table :data="selected.retrieved||[]"><el-table-column prop="rank" label="排名" width="80"/><el-table-column prop="title" label="文档" min-width="220"/><el-table-column prop="documentId" label="文档 ID" min-width="220"/><el-table-column prop="score" label="检索分数" width="110"/><el-table-column label="标注相关" width="110"><template #default="{row}">{{row.relevant==null?'无标注':row.relevant?'是':'否'}}</template></el-table-column></el-table><div class="ps-toolbar"><el-button v-for="reference in selected.references||[]" :key="reference.id" link @click="showReference(reference)">{{reference.title}}</el-button></div>
      <h3>模型评委</h3><el-descriptions :column="2" border><el-descriptions-item label="评分">{{metric(judgeScore)}}</el-descriptions-item><el-descriptions-item label="判断">{{judgeCorrect===true?'正确':judgeCorrect===false?'错误':'未判定'}}</el-descriptions-item><el-descriptions-item label="理由">{{selected.judgeReason||selected.judge?.reason||'未返回'}}</el-descriptions-item></el-descriptions><el-collapse><el-collapse-item title="评委原始输出"><pre class="ps-pre">{{selected.judgeRawOutput||selected.judge?.rawOutput||'未返回原始输出'}}</pre></el-collapse-item></el-collapse>
      <h3>独立人工判断</h3><el-form label-width="110px"><el-form-item label="复核结论"><el-select v-model="conclusion"><el-option label="通过" value="SUPPORTED"/><el-option label="不通过" value="UNSUPPORTED"/><el-option label="需补证据" value="NEEDS_EVIDENCE"/></el-select></el-form-item><el-form-item label="独立评分"><el-select v-model="humanScore" clearable placeholder="可选，1 至 5 分"><el-option v-for="score in 5" :key="score" :label="score+' 分'" :value="score"/></el-select></el-form-item><el-form-item label="判定理由" required><el-input v-model="reason" type="textarea" :rows="4" maxlength="2000"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-button v-hasPermi="['paismart:eval:review']" type="primary" :loading="saving" @click="save">保存复核记录</el-button><h3>复核历史</h3><el-table :data="reviews"><el-table-column label="结论" width="130"><template #default="{row}">{{row.conclusion==='NEEDS_EVIDENCE'?'需补证据':row.correct===true||['PASS','SUPPORTED'].includes(row.conclusion)?'通过':'不通过'}}</template></el-table-column><el-table-column prop="score" label="评分" width="90"/><el-table-column prop="reason" label="理由" min-width="260"/><el-table-column label="复核人" width="130"><template #default="{row}">{{row.reviewer??row.reviewerId}}</template></el-table-column><el-table-column prop="createdAt" label="时间" width="180"/></el-table>
    </template></el-drawer><ReferencePreview v-model="referenceOpen" :reference="reference"/>
  </div>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,shallowRef} from 'vue'
import {useRoute} from 'vue-router'
import {evaluationReport,listReviews,saveReview} from '@/api/paismart/governance'
import type {EvaluationCase,EvaluationReport,Id,Reference,Review} from '@/types/paismart'
import ReferencePreview from '../../chat/components/ReferencePreview.vue'
import {errorText,stateLabel} from '../../composables/usePage'
import {evaluationMetric as metric,verdictLabel} from '../../composables/evaluationPresentation'
import '../../common.css'
const route=useRoute(),evaluationId=ref(String(route.query.evaluationId||'')),report=shallowRef<EvaluationReport>(),selected=shallowRef<EvaluationCase>(),reviews=shallowRef<Review[]>([]),reference=shallowRef<Reference>(),error=ref(''),formError=ref(''),loading=ref(false),saving=ref(false),open=ref(false),referenceOpen=ref(false),conclusion=ref('NEEDS_EVIDENCE'),reason=ref(''),humanScore=ref<number>(),caseKeyword=ref(''),caseDiagnosis=ref(''),onlyReview=ref(false)
const summaryDefinitions:[string,string,boolean?][]=[['totalCases','总样本'],['labeledCases','有相关文档标注'],['retrievalHits','检索命中'],['recallAtK','Recall@K',true],['mrr','平均倒数排名'],['meanExpectedDocCoverage','平均期望文档覆盖率',true],['ndcg','NDCG'],['judgedCases','已评分样本'],['correctCases','评委判对样本'],['meanJudgeScore','平均评委分'],['accuracy','评委准确率',true],['needsHumanReviewCount','需人工复核'],['failedCases','失败样本']]
const summaryCards=computed(()=>summaryDefinitions.map(([key,label,percent])=>({key,label,percent,value:report.value?.summary[key]}))),agreement=computed(()=>report.value?.judgeHumanAgreement)
const partialProgress=computed(()=>{const summary=report.value?.summary,processed=summary?.processedCases,pending=summary?.pendingCases;if(typeof processed!=='number'||typeof pending!=='number'||!Number.isSafeInteger(processed)||!Number.isSafeInteger(pending)||processed<0||pending<=0)return '';return `当前为部分结果：已完成处理 ${processed} 个，待处理 ${pending} 个。指标仅统计已完成且可计算的案例。`})
const agreementMetrics=computed(()=>{const a=agreement.value;return a?[{label:'已复核样本',value:a.reviewedCases},{label:'可比较样本',value:a.comparableCases},{label:'一致样本',value:a.agreedCases},{label:'一致率',value:a.agreementRate,percent:true},{label:'Cohen’s Kappa',value:a.cohensKappa??a.kappa??null},{label:'平均绝对分差',value:a.meanAbsoluteScoreDiff??a.meanScoreDiff??null},{label:'评委判对率',value:a.judgeCorrectRate,percent:true},{label:'人工判对率',value:a.humanCorrectRate,percent:true},{label:'仅人工有结论',value:a.humanOnlyCases}]:[]})
const diagnosisGuide=computed(()=>Object.entries(report.value?.diagnosisGuide??{}).map(([code,description])=>({code,description}))),diagnosisLabel=(code?:string)=>code?report.value?.diagnosisGuide?.[code]??code:'未返回'
function counts(key:string){const source=report.value?.summary[key];return source&&typeof source==='object'?Object.entries(source).map(([name,count])=>({name:key==='diagnosisCounts'?diagnosisLabel(name):name,count})):[]}
const modeCounts=computed(()=>counts('retrievalModeCounts')),diagnosisCounts=computed(()=>counts('diagnosisCounts')),visibleCases=computed(()=>report.value?.cases.filter(row=>(!caseKeyword.value||row.question.includes(caseKeyword.value))&&(!caseDiagnosis.value||row.diagnosis===caseDiagnosis.value)&&(!onlyReview.value||row.needsHumanReview))??[]),judgeScore=computed(()=>selected.value?.judgeScore??selected.value?.judge?.score??null),judgeCorrect=computed(()=>selected.value?.judgeCorrect??selected.value?.judge?.correct)
let serial=0,reviewSerial=0
async function load(){if(!evaluationId.value.trim()){error.value='请输入评测记录 ID';return}const current=++serial;loading.value=true;error.value='';try{const response=await evaluationReport(evaluationId.value);if(current===serial)report.value=response.data}catch(e){if(current===serial)error.value=errorText(e)}finally{if(current===serial)loading.value=false}}
async function select(row:EvaluationCase|null){if(!row)return;const current=++reviewSerial;selected.value=row;reviews.value=[];formError.value='';reason.value='';humanScore.value=undefined;conclusion.value='NEEDS_EVIDENCE';open.value=true;try{const response=await listReviews(evaluationId.value,row.id);if(current===reviewSerial)reviews.value=response.rows}catch(e){if(current===reviewSerial)formError.value=errorText(e)}}
function selectById(id:Id){const row=report.value?.cases.find(row=>String(row.id)===String(id));if(row)void select(row)}
async function save(){if(!selected.value)return;if(!reason.value.trim()){formError.value='请填写独立判定理由';return}const caseId=selected.value.id;saving.value=true;formError.value='';try{await saveReview(evaluationId.value,{caseId,conclusion:conclusion.value,reason:reason.value,expectedVersion:selected.value.rowVersion,score:humanScore.value});const response=await listReviews(evaluationId.value,caseId);if(String(selected.value?.id)===String(caseId))reviews.value=response.rows;await load();selected.value=report.value?.cases.find(row=>String(row.id)===String(caseId))}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function download(){if(!report.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`评测报告-${evaluationId.value}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),0)}
function showReference(value:Reference){reference.value=value;referenceOpen.value=true}
onMounted(()=>{if(evaluationId.value)void load()})
</script>
